/**
 * Differential tests (fragment-fusion M1): every compiled predicate — precompiled primitive or interpreter-backed — is
 * pinned to the {@link FragmentInterpreter} oracle over an exhaustive small id matrix covering every inline family,
 * references, unbound, and doubles.
 */
class FragmentPrimitivesTest {

	private static final long UNBOUND = -1L;

	private static long orderedInt(long value) {
		return ValueIds.createId(ValueIds.T_ORD_INTEGER, value + ValueIds.ORDERED_BIAS);
	}

	private static long[] idMatrix() {
		List<Long> ids = new ArrayList<>();
		ids.add(UNBOUND);
		ids.add(0L); // T_PTR zero id — degenerate but must not crash
		ids.add(1L); // inline double (low bit set)
		ids.add(0x7fff_ffff_ffff_fff1L); // another double pattern
		for (long v : new long[] { Long.MIN_VALUE / 1024, -100, -1, 0, 1, 17, 18, 64, 65, 100, 1L << 50 }) {
			ids.add(orderedInt(v));
		}
		ids.add(ValueIds.createId(ValueIds.T_ORD_LONG, 42 + ValueIds.ORDERED_BIAS));
		ids.add(ValueIds.createId(ValueIds.T_URI, 7));
		ids.add(ValueIds.createId(ValueIds.T_URI, 8));
		ids.add(ValueIds.createId(ValueIds.T_BNODE, 7));
		ids.add(ValueIds.createId(ValueIds.T_TRIPLE, 3));
		ids.add(ValueIds.createId(ValueIds.T_LITERAL, 7));
		ids.add(ValueIds.createId(ValueIds.T_LITERAL, 9));
		ids.add(ValueIds.createId(ValueIds.T_INTEGER, 55)); // legacy zigzag integer: inline but not ordered
		ids.add(ValueIds.createId(ValueIds.T_DECIMAL, 91));
		ids.add(ValueIds.createId(ValueIds.T_DATE, 2023L | 5L << 13 | 14L << 17));
		long[] result = new long[ids.size()];
		for (int i = 0; i < result.length; i++) {
			result[i] = ids.get(i);
		}
		return result;
	}

	private static void assertDifferentialUnary(FragmentIR ir, FragmentBinding binding) {
		LongPredicateFragment compiled = FragmentCompiler.compilePredicate(ir);
		for (long a0 : idMatrix()) {
			PredicateStatus oracle = FragmentInterpreter.testPredicate(ir, a0, UNBOUND, UNBOUND, binding);
			PredicateStatus actual = compiled.test(a0, UNBOUND, UNBOUND, binding);
			assertThat(actual).as("a0=%s ir=%s", Long.toHexString(a0), ir.shapeKey()).isEqualTo(oracle);
		}
	}

	private static void assertDifferentialBinary(FragmentIR ir, FragmentBinding binding) {
		LongPredicateFragment compiled = FragmentCompiler.compilePredicate(ir);
		for (long a0 : idMatrix()) {
			for (long a1 : idMatrix()) {
				PredicateStatus oracle = FragmentInterpreter.testPredicate(ir, a0, a1, UNBOUND, binding);
				PredicateStatus actual = compiled.test(a0, a1, UNBOUND, binding);
				assertThat(actual).as("a0=%s a1=%s ir=%s", Long.toHexString(a0), Long.toHexString(a1), ir.shapeKey())
						.isEqualTo(oracle);
			}
		}
	}

	@Test
	void isBoundPrimitiveMatchesOracle() {
		assertDifferentialUnary(FragmentIR.predicate(new IsBound(new Argument(0))), FragmentBinding.EMPTY);
	}

	@Test
	void typeGuardPrimitivesMatchOracle() {
		for (IdCapability capability : IdCapability.values()) {
			assertDifferentialUnary(FragmentIR.predicate(new TypeGuard(new Argument(0), capability)),
					FragmentBinding.EMPTY);
		}
	}

	@Test
	void orderedCompareToConstantMatchesOracleForEveryOpAndConstantKind() {
		long[] constants = { orderedInt(18), orderedInt(-5), UNBOUND, ValueIds.createId(ValueIds.T_LITERAL, 3),
				ValueIds.createId(ValueIds.T_INTEGER, 18) };
		for (FragmentCompareOp op : FragmentCompareOp.values()) {
			for (long constant : constants) {
				FragmentBinding binding = FragmentBinding.of(constant);
				assertDifferentialUnary(FragmentIR.predicate(new Compare(op,
						new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER),
						new DecodeInline(new Constant(0), DecodeInline.InlineKind.ORDERED_INTEGER))), binding);
				// flipped: constant on the left
				assertDifferentialUnary(FragmentIR.predicate(new Compare(op,
						new DecodeInline(new Constant(0), DecodeInline.InlineKind.ORDERED_INTEGER),
						new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER))), binding);
			}
		}
	}

	@Test
	void orderedCompareBetweenArgumentsMatchesOracle() {
		for (FragmentCompareOp op : FragmentCompareOp.values()) {
			assertDifferentialBinary(FragmentIR.predicate(new Compare(op,
					new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER),
					new DecodeInline(new Argument(1), DecodeInline.InlineKind.ORDERED_INTEGER))),
					FragmentBinding.EMPTY);
		}
	}

	@Test
	void rawIdComparesMatchOracle() {
		for (FragmentCompareOp op : FragmentCompareOp.values()) {
			assertDifferentialBinary(FragmentIR.predicate(new Compare(op, new Argument(0), new Argument(1))),
					FragmentBinding.EMPTY);
			for (long constant : idMatrix()) {
				FragmentBinding binding = FragmentBinding.of(constant);
				assertDifferentialUnary(FragmentIR.predicate(new Compare(op, new Argument(0), new Constant(0))),
						binding);
				assertDifferentialUnary(FragmentIR.predicate(new Compare(op, new Constant(0), new Argument(0))),
						binding);
			}
		}
	}

	@Test
	void sameTermPrimitiveMatchesOracle() {
		assertDifferentialBinary(
				FragmentIR.predicate(new FragmentNode.SameTerm(new Argument(0), new Argument(1))),
				FragmentBinding.EMPTY);
		for (long constant : idMatrix()) {
			FragmentBinding binding = FragmentBinding.of(constant);
			assertDifferentialUnary(
					FragmentIR.predicate(new FragmentNode.SameTerm(new Argument(0), new Constant(0))), binding);
			assertDifferentialUnary(
					FragmentIR.predicate(new FragmentNode.SameTerm(new Constant(0), new Argument(0))), binding);
		}
	}

	/** sameTerm is term identity: equal-valued ordered integers of different datatypes are FALSE, never TRUE. */
	@Test
	void sameTermIsIdIdentityNotNumericEquality() {
		long intFortyTwo = ValueIds.createId(ValueIds.T_ORD_INT, 42 + ValueIds.ORDERED_BIAS);
		long longFortyTwo = ValueIds.createId(ValueIds.T_ORD_LONG, 42 + ValueIds.ORDERED_BIAS);
		FragmentIR ir = FragmentIR.predicate(new FragmentNode.SameTerm(new Argument(0), new Argument(1)));
		assertThat(FragmentInterpreter.testPredicate(ir, intFortyTwo, longFortyTwo, UNBOUND, FragmentBinding.EMPTY))
				.isEqualTo(PredicateStatus.FALSE);
		assertThat(FragmentInterpreter.testPredicate(ir, intFortyTwo, intFortyTwo, UNBOUND, FragmentBinding.EMPTY))
				.isEqualTo(PredicateStatus.TRUE);
		assertThat(FragmentInterpreter.testPredicate(ir, UNBOUND, intFortyTwo, UNBOUND, FragmentBinding.EMPTY))
				.isEqualTo(PredicateStatus.ERROR);
	}

	@Test
	void orderedRangePrimitiveMatchesOracle() {
		long[][] bounds = { { orderedInt(18), orderedInt(65) }, { orderedInt(65), orderedInt(18) },
				{ UNBOUND, orderedInt(65) }, { orderedInt(18), ValueIds.createId(ValueIds.T_LITERAL, 3) } };
		for (long[] pair : bounds) {
			FragmentBinding binding = FragmentBinding.of(pair);
			assertDifferentialUnary(FragmentIR.predicate(new BooleanAnd(
					new Compare(FragmentCompareOp.GE,
							new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER),
							new DecodeInline(new Constant(0), DecodeInline.InlineKind.ORDERED_INTEGER)),
					new Compare(FragmentCompareOp.LT,
							new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER),
							new DecodeInline(new Constant(1), DecodeInline.InlineKind.ORDERED_INTEGER)))),
					binding);
		}
	}

	@Test
	void nonPrimitiveShapesFallBackToInterpreterBackend() {
		// an escape inside an OR is not a primitive shape; the compiled form must still match the oracle
		FragmentIR ir = FragmentIR.predicate(new BooleanOr(
				new TypeGuard(new Argument(0), IdCapability.URI_REFERENCE), new Escape(0)));
		FragmentBinding binding = FragmentBinding.EMPTY.withFallback((a0, a1, a2) -> false);
		assertDifferentialUnary(ir, binding);
	}

	@Test
	void compiledFragmentsAreCachedByShapeKey() {
		FragmentIR first = FragmentIR.predicate(new Compare(FragmentCompareOp.GE,
				new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER),
				new DecodeInline(new Constant(0), DecodeInline.InlineKind.ORDERED_INTEGER)));
		FragmentIR second = FragmentIR.predicate(new Compare(FragmentCompareOp.GE,
				new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER),
				new DecodeInline(new Constant(0), DecodeInline.InlineKind.ORDERED_INTEGER)));
		assertThat(FragmentCompiler.compilePredicate(first)).isSameAs(FragmentCompiler.compilePredicate(second));
	}

	@Test
	void filterSiteContractOnCompiledFragments() {
		FragmentIR range = FragmentIR.predicate(new Compare(FragmentCompareOp.GE,
				new DecodeInline(new Argument(0), DecodeInline.InlineKind.ORDERED_INTEGER),
				new DecodeInline(new Constant(0), DecodeInline.InlineKind.ORDERED_INTEGER)));
		LongPredicateFragment compiled = FragmentCompiler.compilePredicate(range);
		FragmentBinding binding = FragmentBinding.of(orderedInt(18)).withFallback((a0, a1, a2) -> a0 == 12345L);
		assertThat(compiled.testAtFilterSite(orderedInt(20), UNBOUND, UNBOUND, binding)).isTrue();
		assertThat(compiled.testAtFilterSite(orderedInt(17), UNBOUND, UNBOUND, binding)).isFalse();
		// unbound argument: ERROR folds to reject without consulting the fallback
		assertThat(compiled.testAtFilterSite(UNBOUND, UNBOUND, UNBOUND, binding)).isFalse();
		// dictionary literal escapes to the exact fallback
		assertThat(compiled.testAtFilterSite(12345L & ~1L, UNBOUND, UNBOUND, binding)).isFalse();
		assertThat(compiled.testAtFilterSite(ValueIds.createId(ValueIds.T_LITERAL, 4), UNBOUND, UNBOUND,
				binding.withFallback((a0, a1, a2) -> true))).isTrue();
	}
}
